const r = await tools.write_stdin({session_id:36674,chars:"delta=np.array([0.673,-3.879,1.20])-np.array(obs2.meta['proprio']['now'][26:29])
print('delta',delta,'sv',np.linalg.svd(J)[1])
for lam in [0.01,0.05,0.1,0.2]:
 dq=J.T@np.linalg.solve(J@J.T+lam**2*np.eye(3),delta)
 print(lam, np.round(dq,3), 'max',np.max(np.abs(dq)),'pred',np.round(J@dq,3))
",yield_time_ms:10000,max_output_tokens:1000});
