const r = await tools.write_stdin({session_id:36674,chars:"exec("""def _rotvec(R):
 c=np.clip((np.trace(R)-1.0)/2.0,-1.0,1.0); t=float(np.arccos(c)); v=np.array([R[2,1]-R[1,2],R[0,2]-R[2,0],R[1,0]-R[0,1]])
 return 0.5*v if t<1e-7 else (t/(2*np.sin(t)))*v
def pose_jacobian(q, base_obs, eps=0.04, steps=10):
 T0=np.asarray(base_obs.meta['cameras']['robot0_eye_in_hand']['cam2world_gl']); R0,p0=T0[:3,:3],np.asarray(base_obs.meta['proprio']['now'][26:29],float); Jp=[]; Jw=[]
 for j in range(7):
  qp=np.asarray(q,float).copy(); qp[j]+=eps
  r.submit('joint_position',[joint_action(qp,grip=-1)]*steps,cameras=['robot0_eye_in_hand'],video='none',note=f'pose probe + joint {j+1}')
  o=r.get_obs(cameras=['robot0_eye_in_hand'],include_depth=False,video='none'); T1=np.asarray(o.meta['cameras']['robot0_eye_in_hand']['cam2world_gl']); p1=np.asarray(o.meta['proprio']['now'][26:29],float)
  Jp.append((p1-p0)/eps); Jw.append(_rotvec(T1[:3,:3]@R0.T)/eps)
  r.submit('joint_position',[joint_action(q,grip=-1)]*steps,cameras=['robot0_eye_in_hand'],video='none',note=f'return probe joint {j+1}')
 return np.vstack([np.array(Jp).T,np.array(Jw).T])
""")
qcur=np.array(res1.proprio[-1,4:11],float)
J6=pose_jacobian(qcur,obs3)
print('qcur',np.round(qcur,3),'eef',np.round(r.status(),3) if False else np.round(obs3.meta['proprio']['now'][26:29],3))
print('J6\n',np.round(J6,3))
",yield_time_ms:1000,max_output_tokens:1000});
text(r.output);

